{"implementation": "def solve(case):
    payload = case['payload']
    segments = payload['segments']
    budget = payload['budget']

    # Validate fields
    for seg in segments:
        if not all(k in seg for k in ('name', 'importance', 'minimum', 'capacity')):
            return {"error": "Missing fields in segment"}
        if not isinstance(seg['importance'], (int, float)) or not isinstance(seg['minimum'], int) or not isinstance(seg['capacity'], int):
            return {"error": "Invalid field types"}

    min_sum = sum(seg['minimum'] for seg in segments)
    cap_sum = sum(seg['capacity'] for seg in segments)

    if budget < min_sum or budget > cap_sum:
        return {"error": "Budget out of range"}

    # Initial allocation at minimum
    alloc = {seg['name']: seg['minimum'] for seg in segments}
    allocated = min_sum
    remaining = budget - allocated

    # While there is budget left
    while remaining > 0:
        best_seg = None
        best_ratio = -1.0
        for seg in segments:
            name = seg['name']
            if alloc[name] >= seg['capacity']:
                continue
            next_pos = alloc[name] + 1
            ratio = seg['importance'] / next_pos
            if ratio > best_ratio:
                best_ratio = ratio
                best_seg = seg
        if best_seg is None:
            # Should not happen if budget <= cap_sum
            break
        alloc[best_seg['name']] += 1
        allocated += 1
        remaining -= 1

    name_mapping = [seg['name'] for seg in segments]
    return {
        "allocations": alloc,
        "name_mapping": name_mapping,
        "total": allocated
    }
"}
